wave2 = await {
  fixed_points: tools.search({
    queries: [
      "expected number fixed points random permutation indicator variables",
      "expected number isolated heads coin toss indicator linearity expectation"
    ],
    limit: 300
  })?,
  consecutive: tools.search({
    queries: [
      "expected number adjacent equal elements random sequence indicator",
      "expected number consecutive matching pairs random sequence linearity"
    ],
    limit: 300
  })?,
  rises_descents: tools.search({
    queries: [
      "expected number rises descents random permutation indicator method",
      "expected occurrences pattern random word indicator random variable"
    ],
    limit: 300
  })?,
  discover1: tools.discover_docs({
    target_query: "indicator random variables linearity of expectation count local pattern in random sequence closed-form ratio",
    context_pairs: [
      {
        positive_text: "We toss an unbiased coin to obtain a sequence of heads and tails, continuing until $r$ heads have occurred. In this sequence, there will be some number $R$ of runs (runs of heads or runs of tails) and some number $X$ of isolated heads",
        negative_text: "An urn contains $n$ numbered balls and $k$ blue balls. Balls are drawn and replaced until a blue ball is obtained. A repetition is noted each time a numbered ball is obtained that had been drawn previously"
      },
      {
        positive_text: "A fair coin is tossed $n$ times with $n\\ge 2$. Let $R$ be the resulting number of runs of the same face, and $X$ the number of isolated heads. Show that the covariance of the random variables $R$ and $X$ is $n/8$.",
        negative_text: "An urn contains $n$ red balls and $m$ blue balls. The red balls are numbered $1$ to $n$. Balls are drawn at random without replacement until a blue ball is drawn"
      },
      {
        positive_text: "Let $\\sigma$ be a random permutation of the set $1,2,\\ldots,n$. Find the expectation of number of the elements which are fixed points of the permutation $\\sigma$.",
        negative_text: "Let $p_k(m,n)$ be the probability of getting at least one ball of each color when $k$ balls are chosen randomly from a population of $m$ white balls and $n$ black balls"
      }
    ],
    limit: 300
  })?
}

